export class PharmacyPageComponent implements OnInit {
  private readonly pharmacy = inject(PharmacyService); private readonly toast = inject(ToastService); private readonly route = inject(ActivatedRoute); private readonly router = inject(Router);
  protected readonly loading = signal(true); protected readonly saving = signal(false); protected readonly dashboard = signal<PharmacyDashboard | null>(null); protected readonly queue = signal<PrescriptionQueueItem[]>([]); protected readonly dispensings = signal<RecentDispensing[]>([]); protected readonly medicines = signal<Medicine[]>([]); protected readonly drugOptions = signal<DrugMasterOptions | null>(null); protected readonly drugView = signal<'brands'|'generics'>('brands'); protected readonly formulary = signal<FormularyPolicy[]>([]); protected readonly formularyAll = signal<FormularyPolicy[]>([]); protected readonly formularyOptions = signal<FormularyOptions | null>(null); protected readonly interactions = signal<DrugInteractionRule[]>([]); protected readonly interactionAll = signal<DrugInteractionRule[]>([]); protected readonly interactionOptions = signal<DrugInteractionOptions | null>(null); protected readonly stock = signal<StockBatch[]>([]); protected readonly selectedPrescription = signal<PrescriptionDetail | null>(null); protected readonly dialog = signal<PharmacyDialog>(null); protected readonly activeTab = signal<PharmacyTab>('dashboard');
  protected queueSearch=''; protected queueStatus=''; protected medicineSearch=''; protected formularySearch=''; protected formularyStatus:FormularyStatus|''=''; protected formularyDepartment=''; protected interactionSearch=''; protected interactionSeverity:DrugInteractionSeverity|''=''; protected interactionBehavior:DrugInteractionBehavior|''=''; protected stockSearch=''; protected stockState=''; protected dispenseNotes=''; protected dispenseLines: DispenseLine[]=[]; protected editingMedicineId=''; protected editingGenericId=''; protected editingInteractionId=''; protected selectedFormularyDrug:FormularyPolicy|null=null; private returnToMedicine=false;
  protected medicineForm: SaveMedicineRequest=emptyMedicine(); protected genericForm: SaveGenericDrugRequest=emptyGeneric(); protected formularyForm:SaveFormularyPolicyRequest=emptyFormularyPolicy(); protected interactionForm:SaveDrugInteractionRequest=emptyInteraction(); protected batchForm: ReceiveBatchRequest=emptyBatch();
  protected readonly masterSections:Array<{type:DrugMasterType;label:string}>=[{type:'dosage-forms',label:'Dosage Forms'},{type:'routes',label:'Routes'},{type:'categories',label:'Therapeutic Categories'},{type:'manufacturers',label:'Manufacturers'}];
  protected readonly formularyStatuses:Array<{value:FormularyStatus;label:string;description:string;icon:string;tone:string}>=[{value:'APPROVED',label:'Approved',description:'Standard use',icon:'check_circle',tone:'tone-approved'},{value:'RESTRICTED',label:'Restricted',description:'Controlled access',icon:'gpp_maybe',tone:'tone-restricted'},{value:'NON_FORMULARY',label:'Non-formulary',description:'Outside catalogue',icon:'remove_circle_outline',tone:'tone-nonformulary'},{value:'BLOCKED',label:'Blocked',description:'Cannot prescribe',icon:'block',tone:'tone-blocked'}];
  protected readonly masterDrafts:Record<DrugMasterType,{code:string;name:string}>={'dosage-forms':{code:'',name:''},routes:{code:'',name:''},categories:{code:'',name:''},manufacturers:{code:'',name:''}};
  protected readonly tabs=[{value:'dashboard' as PharmacyTab,label:'Dashboard',icon:'dashboard',badge:()=>0},{value:'prescriptions' as PharmacyTab,label:'Prescription Queue',icon:'prescriptions',badge:()=>this.dashboard()?.pendingPrescriptions||0},{value:'dispensing' as PharmacyTab,label:'Dispensing',icon:'medication',badge:()=>0},{value:'medicines' as PharmacyTab,label:'Drug Master',icon:'pill',badge:()=>0},{value:'formulary' as PharmacyTab,label:'Formulary',icon:'verified_user',badge:()=>this.formularyAll().filter(x=>x.statusCode==='RESTRICTED').length},{value:'interactions' as PharmacyTab,label:'Drug Interactions',icon:'health_and_safety',badge:()=>this.interactionAll().filter(x=>x.behaviorCode==='BLOCK').length},{value:'stock' as PharmacyTab,label:'Stock & Batches',icon:'inventory_2',badge:()=>this.dashboard()?.lowStockItems||0}];
  protected readonly primaryLabel=computed(()=>this.activeTab()==='stock'?'Receive Batch':this.activeTab()==='prescriptions'?'Open Next Prescription':this.activeTab()==='formulary'?'Review Restricted':this.activeTab()==='interactions'?'New Interaction Rule':'Add Medicine');
  async ngOnInit(){const tab=this.route.snapshot.queryParamMap.get('tab') as PharmacyTab|null;if(tab&&this.tabs.some(x=>x.value===tab))this.activeTab.set(tab);await this.refresh();}
  async refresh(){this.loading.set(true);const [dashboard,queue,dispensings,medicines,options,formulary,formularyOptions,interactions,interactionOptions,stock]=await Promise.allSettled([this.pharmacy.dashboard(),this.pharmacy.prescriptions(),this.pharmacy.dispensings(),this.pharmacy.medicines(),this.pharmacy.drugMasterOptions(),this.pharmacy.formulary(),this.pharmacy.formularyOptions(),this.pharmacy.interactions(),this.pharmacy.interactionOptions(),this.pharmacy.stock()]);if(dashboard.status==='fulfilled')this.dashboard.set(dashboard.value);if(queue.status==='fulfilled')this.queue.set(queue.value);if(dispensings.status==='fulfilled')this.dispensings.set(dispensings.value);if(medicines.status==='fulfilled')this.medicines.set(medicines.value);if(options.status==='fulfilled')this.drugOptions.set(options.value);if(formulary.status==='fulfilled'){this.formulary.set(formulary.value);this.formularyAll.set(formulary.value);}if(formularyOptions.status==='fulfilled')this.formularyOptions.set(formularyOptions.value);if(interactions.status==='fulfilled'){this.interactions.set(interactions.value);this.interactionAll.set(interactions.value);}if(interactionOptions.status==='fulfilled')this.interactionOptions.set(interactionOptions.value);if(stock.status==='fulfilled')this.stock.set(stock.value);const failed=[dashboard,queue,dispensings,medicines,options,formulary,formularyOptions,interactions,interactionOptions,stock].find(x=>x.status==='rejected') as PromiseRejectedResult|undefined;if(failed)this.toast.error('Pharmacy could not be fully loaded',getApiErrorMessage(failed.reason));this.loading.set(false);}
  protected setTab(tab:PharmacyTab){this.activeTab.set(tab);void this.router.navigate([], {relativeTo:this.route,queryParams:{tab},queryParamsHandling:'merge',replaceUrl:true});}
  protected primaryAction(){if(this.activeTab()==='stock'){this.openBatch();return;}if(this.activeTab()==='prescriptions'){const next=this.queue().find(x=>x.statusCode!=='DISPENSED');if(next){void this.openDispense(next);return;}this.toast.info('Queue is clear','There are no prescriptions waiting to dispense.');return;}if(this.activeTab()==='formulary'){const restricted=this.formulary().find(x=>x.statusCode==='RESTRICTED');if(restricted)this.editFormulary(restricted);else this.toast.info('No restricted drugs','The current formulary has no restricted policies.');return;}if(this.activeTab()==='interactions'){this.openInteraction();return;}this.openMedicine();}
  protected async loadQueue(){try{this.queue.set(await this.pharmacy.prescriptions(this.queueSearch,this.queueStatus));}catch(error){this.toast.error('Queue could not be loaded',this.errorMessage(error));}}
  protected async loadMedicines(){try{this.medicines.set(await this.pharmacy.medicines(this.medicineSearch));}catch(error){this.toast.error('Drug master could not be loaded',this.errorMessage(error));}}
  protected async loadFormulary(){try{this.formulary.set(await this.pharmacy.formulary(this.formularySearch,this.formularyStatus,this.formularyDepartment));}catch(error){this.toast.error('Formulary could not be loaded',this.errorMessage(error));}}
  protected filterFormularyStatus(status:FormularyStatus){this.formularyStatus=this.formularyStatus===status?'':status;void this.loadFormulary();}
  protected formularyCount(status:FormularyStatus){return this.formularyAll().filter(x=>x.statusCode===status).length;}
  protected formularyClass(status:FormularyStatus){return status==='APPROVED'?'success':status==='RESTRICTED'?'warning':status==='BLOCKED'?'blocked':'nonformulary';}
  protected editFormulary(policy:FormularyPolicy){this.selectedFormularyDrug=policy;this.formularyForm={statusCode:policy.statusCode,allDepartmentsAllowed:policy.allDepartmentsAllowed,allowedDepartments:[...policy.allowedDepartments],restrictionReason:policy.restrictionReason||'',alternativeMedicineId:policy.alternativeMedicineId,approvalRequired:policy.approvalRequired,approvalRole:policy.approvalRole||'',effectiveFrom:policy.effectiveFrom,effectiveTo:policy.effectiveTo,notes:policy.notes||''};this.dialog.set('formulary');}
  protected setFormularyStatus(status:FormularyStatus){this.formularyForm.statusCode=status;if(status==='APPROVED')this.formularyForm.allDepartmentsAllowed=true;if(status==='BLOCKED'||status==='NON_FORMULARY'){this.formularyForm.allDepartmentsAllowed=false;this.formularyForm.allowedDepartments=[];this.formularyForm.approvalRequired=false;}}
  protected alternativeDrugs(currentId:string){return(this.formularyOptions()?.drugs||[]).filter(x=>x.id!==currentId);}
  protected departmentSelected(department:string){return this.formularyForm.allowedDepartments.includes(department);}
  protected toggleDepartment(department:string,selected:boolean){this.formularyForm.allowedDepartments=selected?[...new Set([...this.formularyForm.allowedDepartments,department])]:this.formularyForm.allowedDepartments.filter(x=>x!==department);}
  protected async saveFormulary(){const policy=this.selectedFormularyDrug;if(!policy)return;if(this.formularyForm.statusCode==='RESTRICTED'&&!this.formularyForm.restrictionReason.trim()){this.toast.warning('Restriction reason required');return;}if(this.formularyForm.statusCode==='RESTRICTED'&&!this.formularyForm.allDepartmentsAllowed&&!this.formularyForm.allowedDepartments.length){this.toast.warning('Select an allowed department','Restricted drugs require at least one allowed department.');return;}this.saving.set(true);try{await this.pharmacy.saveFormularyPolicy(policy.medicineId,this.formularyForm);this.toast.success('Formulary policy saved',`${policy.drugName} is now ${this.statusLabel(this.formularyForm.statusCode)}.`);this.closeDialog();const all=await this.pharmacy.formulary();this.formularyAll.set(all);await this.loadFormulary();}catch(error){this.toast.error('Formulary policy could not be saved',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected async loadInteractions(){try{this.interactions.set(await this.pharmacy.interactions(this.interactionSearch,this.interactionSeverity,this.interactionBehavior));}catch(error){this.toast.error('Interaction rules could not be loaded',this.errorMessage(error));}}
  protected interactionCount(behavior:DrugInteractionBehavior){return this.interactionAll().filter(x=>x.isActive&&x.behaviorCode===behavior).length;}
  protected filterInteractionBehavior(behavior:DrugInteractionBehavior){this.interactionBehavior=this.interactionBehavior===behavior?'':behavior;void this.loadInteractions();}
  protected interactionTone(severity:DrugInteractionSeverity){return severity==='CONTRAINDICATED'?'danger':severity==='MAJOR'?'blocked':severity==='MODERATE'?'warning':'success';}
  protected behaviorDescription(behavior:DrugInteractionBehavior){return behavior==='BLOCK'?'Stop prescribing':behavior==='REQUIRE_OVERRIDE'?'Reason required to continue':behavior==='WARN'?'Show warning and continue':'Display guidance';}
  protected openInteraction(){this.editingInteractionId='';this.interactionForm=emptyInteraction();this.dialog.set('interaction');}
  protected editInteraction(rule:DrugInteractionRule){this.editingInteractionId=rule.id;this.interactionForm={genericDrugAId:rule.genericDrugAId,genericDrugBId:rule.genericDrugBId,severity:rule.severity,behaviorCode:rule.behaviorCode,description:rule.description,clinicalRecommendation:rule.clinicalRecommendation,reviewNotes:rule.reviewNotes||'',isActive:rule.isActive};this.dialog.set('interaction');}
  protected async saveInteraction(){const form=this.interactionForm;if(!form.genericDrugAId||!form.genericDrugBId||form.genericDrugAId===form.genericDrugBId||!form.description.trim()||!form.clinicalRecommendation.trim()){this.toast.warning('Complete the clinical rule','Select two different generic drugs and enter the interaction and recommendation.');return;}this.saving.set(true);try{if(this.editingInteractionId)await this.pharmacy.updateInteraction(this.editingInteractionId,form);else await this.pharmacy.createInteraction(form);this.toast.success('Interaction rule saved','Clinical review metadata has been recorded.');this.closeDialog();const all=await this.pharmacy.interactions();this.interactionAll.set(all);await this.loadInteractions();}catch(error){this.toast.error('Interaction rule could not be saved',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected async loadStock(){try{this.stock.set(await this.pharmacy.stock(this.stockSearch,this.stockState));}catch(error){this.toast.error('Stock could not be loaded',this.errorMessage(error));}}
  protected openStockState(state:string){this.stockState=state;this.setTab('stock');void this.loadStock();}
  protected openMedicine(){this.editingMedicineId='';this.medicineForm=emptyMedicine();const options=this.drugOptions();if(options){this.medicineForm.dosageFormId=options.dosageForms.find(x=>x.code==='TABLET')?.id||'';this.medicineForm.routeId=options.routes.find(x=>x.code==='ORAL')?.id||'';this.medicineForm.therapeuticCategoryId=options.therapeuticCategories.find(x=>x.code==='GENERAL')?.id||'';}this.dialog.set('medicine');}
  protected editMedicine(drug:Medicine){this.editingMedicineId=drug.id;this.medicineForm={code:drug.code,name:drug.name,genericDrugId:drug.genericDrugId||'',dosageFormId:drug.dosageFormId||'',strength:drug.strength,routeId:drug.routeId||'',unit:drug.unit,manufacturerId:drug.manufacturerId,therapeuticCategoryId:drug.therapeuticCategoryId||'',packSize:drug.packSize,reorderLevel:drug.reorderLevel,salePrice:drug.salePrice,taxPercent:drug.taxPercent,prescriptionRequired:drug.prescriptionRequired,notes:drug.notes||'',isFormulary:drug.isFormulary,isControlled:drug.isControlled,requiresColdChain:drug.requiresColdChain,isActive:drug.isActive};this.dialog.set('medicine');}
  protected async saveMedicine(){if(!this.medicineForm.code.trim()||!this.medicineForm.name.trim()||!this.medicineForm.genericDrugId||!this.medicineForm.dosageFormId||!this.medicineForm.routeId||!this.medicineForm.therapeuticCategoryId||!this.medicineForm.unit.trim()){this.toast.warning('Required fields missing','Code, brand, generic drug, dosage form, route, category, and unit are required.');return;}this.saving.set(true);try{if(this.editingMedicineId)await this.pharmacy.updateMedicine(this.editingMedicineId,this.medicineForm);else await this.pharmacy.createMedicine(this.medicineForm);this.toast.success('Drug saved','Generic and brand mapping updated.');this.closeDialog();await Promise.all([this.loadMedicines(),this.loadDrugOptions(),this.loadStock()]);}catch(error){this.toast.error('Drug could not be saved',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected activeGenerics(){return(this.drugOptions()?.genericDrugs||[]).filter(x=>x.isActive);}
  protected activeOptions(group:DrugOptionGroup){return this.optionList(group).filter(x=>x.isActive);}
  protected genericSelected(){const generic=this.drugOptions()?.genericDrugs.find(x=>x.id===this.medicineForm.genericDrugId);if(generic?.therapeuticCategoryId)this.medicineForm.therapeuticCategoryId=generic.therapeuticCategoryId;}
  protected openGeneric(returnToMedicine=false){this.returnToMedicine=returnToMedicine;this.editingGenericId='';this.genericForm=emptyGeneric();this.genericForm.therapeuticCategoryId=this.drugOptions()?.therapeuticCategories.find(x=>x.code==='GENERAL')?.id||'';this.dialog.set('generic');}
  protected editGeneric(generic:GenericDrug){this.returnToMedicine=false;this.editingGenericId=generic.id;this.genericForm={code:generic.code,name:generic.name,therapeuticCategoryId:generic.therapeuticCategoryId||'',description:generic.description||'',isActive:generic.isActive};this.dialog.set('generic');}
  protected async saveGeneric(){if(!this.genericForm.code.trim()||!this.genericForm.name.trim()||!this.genericForm.therapeuticCategoryId){this.toast.warning('Generic details required','Code, generic name, and therapeutic category are required.');return;}this.saving.set(true);try{const result=this.editingGenericId?await this.pharmacy.updateGenericDrug(this.editingGenericId,this.genericForm):await this.pharmacy.createGenericDrug(this.genericForm);await this.loadDrugOptions();if(this.returnToMedicine){this.medicineForm.genericDrugId=result.id;this.genericSelected();this.dialog.set('medicine');}else this.closeDialog();this.toast.success('Generic drug saved');}catch(error){this.toast.error('Generic drug could not be saved',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected openConfiguration(){this.dialog.set('configuration');}
  protected masterList(type:DrugMasterType){return this.optionList(type==='dosage-forms'?'forms':type);}
  protected async addMasterOption(type:DrugMasterType){const draft=this.masterDrafts[type];if(!draft.code.trim()||!draft.name.trim()){this.toast.warning('Code and name required');return;}this.saving.set(true);try{await this.pharmacy.createMasterOption(type,{code:draft.code,name:draft.name,isActive:true,displayOrder:500});draft.code='';draft.name='';await this.loadDrugOptions();this.toast.success('Master option added');}catch(error){this.toast.error('Master option could not be added',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected openBatch(){this.batchForm=emptyBatch();this.dialog.set('batch');}
  protected batchMedicineChanged(){const drug=this.medicines().find(x=>x.id===this.batchForm.medicineId);if(drug){this.batchForm.salePrice=drug.salePrice;this.batchForm.mrp=drug.salePrice;}}
  protected async receiveBatch(){if(!this.batchForm.medicineId||!this.batchForm.batchNumber.trim()||!this.batchForm.expiryDate||this.batchForm.quantity<=0){this.toast.warning('Batch details required','Select a medicine and enter batch, expiry, and quantity.');return;}this.saving.set(true);try{await this.pharmacy.receiveBatch(this.batchForm);this.toast.success('Batch received','Stock ledger updated successfully.');this.closeDialog();await Promise.all([this.loadStock(),this.loadMedicines(),this.loadDashboard()]);}catch(error){this.toast.error('Batch could not be received',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected async openDispense(rx:PrescriptionQueueItem){try{const detail=await this.pharmacy.prescription(rx.id);this.selectedPrescription.set(detail);this.dispenseLines=detail.items.map(item=>({prescriptionItemId:item.id,medicineId:item.medicineId||this.findMedicine(item.medicineName)?.id||'',batchId:'',quantity:1}));this.dispenseLines.forEach((_,i)=>this.medicineChanged(i));this.dispenseNotes='';this.dialog.set('dispense');}catch(error){this.toast.error('Prescription could not be opened',this.errorMessage(error));}}
  protected medicineChanged(index:number){const line=this.dispenseLines[index];const batch=this.batchesFor(line.medicineId)[0];line.batchId=batch?.batchId||'';}
  protected batchesFor(medicineId:string){return this.stock().filter(x=>x.medicineId===medicineId&&x.stockState!=='EXPIRED'&&!x.isQuarantined&&x.availableQuantity>0).sort((a,b)=>a.expiryDate.localeCompare(b.expiryDate));}
  protected canDispense(){return this.dispenseLines.length>0&&this.dispenseLines.every(line=>line.medicineId&&line.batchId&&line.quantity>0&&this.batchesFor(line.medicineId).some(batch=>batch.batchId===line.batchId&&batch.availableQuantity>=line.quantity));}
  protected async confirmDispense(){const rx=this.selectedPrescription();if(!rx||!this.canDispense())return;this.saving.set(true);try{const result=await this.pharmacy.dispense(rx.header.id,this.dispenseLines,this.dispenseNotes);this.toast.success('Prescription dispensed',`${result.dispenseNumber} posted to stock and Billing for ${this.money(result.totalAmount)}.`);this.closeDialog();await this.refresh();this.setTab('dispensing');}catch(error){this.toast.error('Dispensing could not be completed',this.errorMessage(error));}finally{this.saving.set(false);}}
  protected closeDialog(){this.dialog.set(null);this.selectedPrescription.set(null);this.selectedFormularyDrug=null;this.editingInteractionId='';this.returnToMedicine=false;}
  protected money(value:number){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(value||0);}
  protected statusLabel(value:string){return value.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,x=>x.toUpperCase());}
  protected statusClass(value:string){if(['DISPENSED','AVAILABLE','COMPLETED'].includes(value))return 'success';if(['RECEIVED','PARTIALLY_DISPENSED','EXPIRING','LOW_STOCK'].includes(value))return 'warning';if(['EXPIRED','CANCELLED'].includes(value))return 'danger';return '';}
  protected stockClass(value:string){return this.statusClass(value);}
  private optionList(group:DrugOptionGroup):DrugMasterOption[]{const options=this.drugOptions();if(!options)return[];return group==='forms'?options.dosageForms:group==='routes'?options.routes:group==='categories'?options.therapeuticCategories:options.manufacturers;}
  private findMedicine(name:string){return this.medicines().find(x=>x.name.toLowerCase()===name.toLowerCase());}
  private async loadDashboard(){try{this.dashboard.set(await this.pharmacy.dashboard());}catch{/* surfaced by related refresh */}}
  private async loadDrugOptions(){this.drugOptions.set(await this.pharmacy.drugMasterOptions());}
  private errorMessage(error:unknown){return getApiErrorMessage(error as ApiResponse<unknown>);}
}

function emptyMedicine():SaveMedicineRequest{return{code:'',name:'',genericDrugId:'',dosageFormId:'',strength:'',routeId:'',unit:'Tablet',manufacturerId:null,therapeuticCategoryId:'',packSize:1,reorderLevel:10,salePrice:0,taxPercent:0,prescriptionRequired:true,notes:'',isFormulary:true,isControlled:false,requiresColdChain:false,isActive:true};}
function emptyGeneric():SaveGenericDrugRequest{return{code:'',name:'',therapeuticCategoryId:'',description:'',isActive:true};}
function emptyFormularyPolicy():SaveFormularyPolicyRequest{return{statusCode:'APPROVED',allDepartmentsAllowed:true,allowedDepartments:[],restrictionReason:'',alternativeMedicineId:null,approvalRequired:false,approvalRole:'',effectiveFrom:new Date().toISOString().slice(0,10),effectiveTo:null,notes:''};}
function emptyInteraction():SaveDrugInteractionRequest{return{genericDrugAId:'',genericDrugBId:'',severity:'MODERATE',behaviorCode:'WARN',description:'',clinicalRecommendation:'',reviewNotes:'',isActive:true};}
function emptyBatch():ReceiveBatchRequest{return{medicineId:'',batchNumber:'',expiryDate:'',quantity:0,purchasePrice:0,mrp:0,salePrice:0,locationId:null};}
